// test_protocol_c.cpp -- checks dsentry_protocol.h against the spec's example frames and
// the reference deframer, and gives the Python tests a C side to compare with.
// GENERATED by D-SentryCode/tools/gen_protocol.py from D-SentryCode/protocol/protocol_spec.py -- do not edit.
//
// Build (host): clang++ -std=gnu++17 -Wall -Wextra -I D-SentryCode/protocol test_protocol_c.cpp
// Run:  test_protocol_c            self-test; exit 0 when every check passes
//       test_protocol_c --dump     print "ENC <Packet> <hex>" per example and "CRC <hex>"
//       test_protocol_c --deframe  read hex from stdin, print "FRAME <type> <hex> <field=value>..."
//                                  per frame, then "STATS frames=.. crc=.. len=.. junk=.. held=.."
// relay-pc/tests/test_protocol_c.py compiles it and compares both modes with protocol.py.
//
// SPDX-License-Identifier: MIT
#include "dsentry_protocol.h"

#include <stdio.h>
#include <string.h>

static int g_failures = 0;
static int g_checks = 0;

static void check(bool ok, const char* what) {
  g_checks++;
  if (!ok) {
    g_failures++;
    printf("FAIL  %s\n", what);
  }
}

static void print_hex(const uint8_t* data, size_t len) {
  for (size_t i = 0; i < len; i++) printf("%02x", data[i]);
}

