static void print_frame(uint8_t type, const uint8_t* frame, size_t len) {
  printf("FRAME %s ", ds_packet_type_name(type));
  print_hex(frame, len);
  switch (type) {
    case DS_PKT_CONTROL: {
      ds_control_packet_t p;
      ds_control_init(&p);
      uint8_t again[DS_CONTROL_FRAME_LEN];
      bool ok = ds_control_decode(frame, len, &p);
      ok = ok && ds_control_encode(&p, again) == len && memcmp(again, frame, len) == 0;
      print_control_fields(&p);
      printf(" roundtrip=%s", ok ? "ok" : "BAD");
      break;
    }
    case DS_PKT_STATUS: {
      ds_status_packet_t p;
      ds_status_init(&p);
      uint8_t again[DS_STATUS_FRAME_LEN];
      bool ok = ds_status_decode(frame, len, &p);
      ok = ok && ds_status_encode(&p, again) == len && memcmp(again, frame, len) == 0;
      print_status_fields(&p);
      printf(" roundtrip=%s", ok ? "ok" : "BAD");
      break;
    }
    case DS_PKT_TELEMETRY: {
      ds_telemetry_packet_t p;
      ds_telemetry_init(&p);
      uint8_t again[DS_TELEMETRY_FRAME_LEN];
      bool ok = ds_telemetry_decode(frame, len, &p);
      ok = ok && ds_telemetry_encode(&p, again) == len && memcmp(again, frame, len) == 0;
      print_telemetry_fields(&p);
      printf(" roundtrip=%s", ok ? "ok" : "BAD");
      break;
    }
    case DS_PKT_BEACON: {
      ds_beacon_packet_t p;
      ds_beacon_init(&p);
      uint8_t again[DS_BEACON_FRAME_LEN];
      bool ok = ds_beacon_decode(frame, len, &p);
      ok = ok && ds_beacon_encode(&p, again) == len && memcmp(again, frame, len) == 0;
      print_beacon_fields(&p);
      printf(" roundtrip=%s", ok ? "ok" : "BAD");
      break;
    }
    default: break;
  }
  printf("\n");
}

