static const uint8_t k_stream_types[] = {DS_PKT_CONTROL, DS_PKT_STATUS, DS_PKT_STATUS, DS_PKT_BEACON, DS_PKT_TELEMETRY};
static const size_t k_stream_frames = 5;
static const uint32_t k_stream_crc_errors = 3;
static const uint32_t k_stream_len_errors = 4;
static const uint32_t k_stream_junk = 174;
static const uint8_t k_stream_held = 6;

static int self_test(void) {
  static const uint8_t check_input[] = {'1', '2', '3', '4', '5', '6', '7', '8', '9'};
  check(ds_crc8(check_input, sizeof check_input) == DS_CRC8_CHECK, "crc8 check value 0xF4");
  {
    ds_control_packet_t p;
    ds_control_packet_t q;
    uint8_t out[DS_CONTROL_FRAME_LEN];
    example_control(&p);
    check(ds_control_encode(&p, out) == DS_CONTROL_FRAME_LEN, "ControlPacket encode length");
    check(memcmp(out, k_expect_control, sizeof out) == 0, "ControlPacket example frame matches the spec");
    check(ds_control_decode(out, sizeof out, &q) && memcmp(&p, &q, sizeof p) == 0, "ControlPacket decode round trip");
    check(!ds_control_decode(out, sizeof out - 1, &q), "ControlPacket rejects a short frame");
    out[DS_CONTROL_FRAME_LEN - 1] = (uint8_t)(out[DS_CONTROL_FRAME_LEN - 1] ^ 1u);
    check(!ds_control_decode(out, sizeof out, &q), "ControlPacket rejects a bad CRC");
    out[DS_CONTROL_FRAME_LEN - 1] = (uint8_t)(out[DS_CONTROL_FRAME_LEN - 1] ^ 1u);
    out[1] = (uint8_t)(out[1] ^ 1u);
    check(!ds_frame_check(out, sizeof out, DS_PKT_CONTROL), "ControlPacket rejects a wrong len byte");
  }
  {
    ds_status_packet_t p;
    ds_status_packet_t q;
    uint8_t out[DS_STATUS_FRAME_LEN];
    example_status(&p);
    check(ds_status_encode(&p, out) == DS_STATUS_FRAME_LEN, "StatusPacket encode length");
    check(memcmp(out, k_expect_status, sizeof out) == 0, "StatusPacket example frame matches the spec");
    check(ds_status_decode(out, sizeof out, &q) && memcmp(&p, &q, sizeof p) == 0, "StatusPacket decode round trip");
    check(!ds_status_decode(out, sizeof out - 1, &q), "StatusPacket rejects a short frame");
    out[DS_STATUS_FRAME_LEN - 1] = (uint8_t)(out[DS_STATUS_FRAME_LEN - 1] ^ 1u);
    check(!ds_status_decode(out, sizeof out, &q), "StatusPacket rejects a bad CRC");
    out[DS_STATUS_FRAME_LEN - 1] = (uint8_t)(out[DS_STATUS_FRAME_LEN - 1] ^ 1u);
    out[1] = (uint8_t)(out[1] ^ 1u);
    check(!ds_frame_check(out, sizeof out, DS_PKT_STATUS), "StatusPacket rejects a wrong len byte");
  }
  {
    ds_telemetry_packet_t p;
    ds_telemetry_packet_t q;
    uint8_t out[DS_TELEMETRY_FRAME_LEN];
    example_telemetry(&p);
    check(ds_telemetry_encode(&p, out) == DS_TELEMETRY_FRAME_LEN, "TelemetryPacket encode length");
    check(memcmp(out, k_expect_telemetry, sizeof out) == 0, "TelemetryPacket example frame matches the spec");
    check(ds_telemetry_decode(out, sizeof out, &q) && memcmp(&p, &q, sizeof p) == 0, "TelemetryPacket decode round trip");
    check(!ds_telemetry_decode(out, sizeof out - 1, &q), "TelemetryPacket rejects a short frame");
    out[DS_TELEMETRY_FRAME_LEN - 1] = (uint8_t)(out[DS_TELEMETRY_FRAME_LEN - 1] ^ 1u);
    check(!ds_telemetry_decode(out, sizeof out, &q), "TelemetryPacket rejects a bad CRC");
    out[DS_TELEMETRY_FRAME_LEN - 1] = (uint8_t)(out[DS_TELEMETRY_FRAME_LEN - 1] ^ 1u);
    out[1] = (uint8_t)(out[1] ^ 1u);
    check(!ds_frame_check(out, sizeof out, DS_PKT_TELEMETRY), "TelemetryPacket rejects a wrong len byte");
  }
  {
    ds_beacon_packet_t p;
    ds_beacon_packet_t q;
    uint8_t out[DS_BEACON_FRAME_LEN];
    example_beacon(&p);
    check(ds_beacon_encode(&p, out) == DS_BEACON_FRAME_LEN, "BeaconPacket encode length");
    check(memcmp(out, k_expect_beacon, sizeof out) == 0, "BeaconPacket example frame matches the spec");
    check(ds_beacon_decode(out, sizeof out, &q) && memcmp(&p, &q, sizeof p) == 0, "BeaconPacket decode round trip");
    check(!ds_beacon_decode(out, sizeof out - 1, &q), "BeaconPacket rejects a short frame");
    out[DS_BEACON_FRAME_LEN - 1] = (uint8_t)(out[DS_BEACON_FRAME_LEN - 1] ^ 1u);
    check(!ds_beacon_decode(out, sizeof out, &q), "BeaconPacket rejects a bad CRC");
    out[DS_BEACON_FRAME_LEN - 1] = (uint8_t)(out[DS_BEACON_FRAME_LEN - 1] ^ 1u);
    out[1] = (uint8_t)(out[1] ^ 1u);
    check(!ds_frame_check(out, sizeof out, DS_PKT_BEACON), "BeaconPacket rejects a wrong len byte");
  }
  {
    ds_deframer_t d;
    ds_deframer_init(&d);
    size_t found = 0;
    bool order_ok = true;
    for (size_t i = 0; i < sizeof k_stream; i++) {
      uint8_t t = ds_deframer_feed(&d, k_stream[i]);
      while (t != DS_PKT_NONE) {
        if (found >= k_stream_frames || k_stream_types[found] != t ||
            !ds_frame_check(ds_deframer_frame(&d), ds_deframer_frame_len(&d), t)) {
          order_ok = false;
        }
        found++;
        t = ds_deframer_poll(&d);
      }
    }
    check(order_ok && found == k_stream_frames, "deframer finds the expected frames in order");
    check(d.crc_errors == k_stream_crc_errors, "deframer CRC error count");
    check(d.len_errors == k_stream_len_errors, "deframer len error count");
    check(d.junk_bytes == k_stream_junk, "deframer junk byte count");
    check(d.held == k_stream_held, "deframer holds the trailing prefix");
  }
  {
    uint8_t frame[DS_TELEMETRY_FRAME_LEN];
    char hex[DS_AT_DST_HEX_LEN + 1];
    uint8_t back[DS_TELEMETRY_FRAME_LEN];
    ds_telemetry_packet_t p;
    example_telemetry(&p);
    ds_telemetry_encode(&p, frame);
    check(ds_hex_encode(frame, sizeof frame, hex) == DS_AT_DST_HEX_LEN, "hex encode length");
    check(ds_hex_decode(hex, DS_AT_DST_HEX_LEN, back, sizeof back) == sizeof back &&
          memcmp(back, frame, sizeof frame) == 0, "hex round trip");
    check(ds_hex_decode(hex, DS_AT_DST_HEX_LEN - 1, back, sizeof back) == 0, "hex rejects odd length");
    check(ds_hex_decode("0G", 2, back, sizeof back) == 0, "hex rejects a non-digit");
    check(ds_hex_decode("A5ff", 4, back, 1) == 0, "hex rejects overflow");
    check(ds_hex_decode("A5ff", 4, back, 2) == 2 && back[0] == 0xA5 && back[1] == 0xFF, "hex accepts both cases");
  }
  check(strcmp(ds_turret_state_name(DS_STATE_ARMED), "ARMED") == 0, "enum names");
  check(strcmp(ds_esp_mode_name(DS_ESP_MODE_UNKNOWN), "UNKNOWN") == 0, "enum names (255)");
  check(strcmp(ds_fault_name(200), "?") == 0, "unknown enum value");
  printf("%s  test_protocol_c: %d checks, %d failures\n", g_failures ? "FAIL" : "PASS", g_checks, g_failures);
  return g_failures ? 1 : 0;
}

static void dump(void) {
  static const uint8_t check_input[] = {'1', '2', '3', '4', '5', '6', '7', '8', '9'};
  printf("CRC %02x\n", ds_crc8(check_input, sizeof check_input));
  {
    ds_control_packet_t p;
    uint8_t out[DS_CONTROL_FRAME_LEN];
    example_control(&p);
    size_t n = ds_control_encode(&p, out);
    printf("ENC ControlPacket ");
    print_hex(out, n);
    printf("\n");
  }
  {
    ds_status_packet_t p;
    uint8_t out[DS_STATUS_FRAME_LEN];
    example_status(&p);
    size_t n = ds_status_encode(&p, out);
    printf("ENC StatusPacket ");
    print_hex(out, n);
    printf("\n");
  }
  {
    ds_telemetry_packet_t p;
    uint8_t out[DS_TELEMETRY_FRAME_LEN];
    example_telemetry(&p);
    size_t n = ds_telemetry_encode(&p, out);
    printf("ENC TelemetryPacket ");
    print_hex(out, n);
    printf("\n");
  }
  {
    ds_beacon_packet_t p;
    uint8_t out[DS_BEACON_FRAME_LEN];
    example_beacon(&p);
    size_t n = ds_beacon_encode(&p, out);
    printf("ENC BeaconPacket ");
    print_hex(out, n);
    printf("\n");
  }
}

static void deframe_stdin(void) {
  ds_deframer_t d;
  ds_deframer_init(&d);
  int hi = -1;
  int c;
  while ((c = getchar()) != EOF) {
    int v = ds_hex_digit((char)c);
    if (v < 0) continue;
    if (hi < 0) {
      hi = v;
      continue;
    }
    uint8_t t = ds_deframer_feed(&d, (uint8_t)((hi << 4) | v));
    hi = -1;
    while (t != DS_PKT_NONE) {
      print_frame(t, ds_deframer_frame(&d), ds_deframer_frame_len(&d));
      t = ds_deframer_poll(&d);
    }
  }
  printf("STATS frames=%lu crc=%lu len=%lu junk=%lu held=%u\n", (unsigned long)d.frames,
         (unsigned long)d.crc_errors, (unsigned long)d.len_errors, (unsigned long)d.junk_bytes,
         (unsigned)d.held);
}

int main(int argc, char** argv) {
  if (argc > 1 && strcmp(argv[1], "--dump") == 0) {
    dump();
    return 0;
  }
  if (argc > 1 && strcmp(argv[1], "--deframe") == 0) {
    deframe_stdin();
    return 0;
  }
  return self_test();
}
